#define TABLE_MAX_NUM 10
#define TABLE_NODE_SIZE 100

uint8_t *g_shareTable[TABLE_MAX_NUM] = {0};

int CreateShareTable(void)
{
    for (uint8_t i = 0; i < TABLE_MAX_NUM; i++) {
        g_shareTable[i] = malloc(TABLE_NODE_SIZE);
        if (g_shareTable[i] == NULL) {
            continue;
        }
    }

    return 0;
}

void DestroyShareTable(void)
{
    for (uint8_t i = 0; i < TABLE_MAX_NUM; i++) {
        if (g_shareTable[i] == NULL) {
            continue;
        }

        free(g_shareTable[i]);
        g_shareTable[i] = NULL;
    }
}

uint8_t *FindShareTableNode(uint8_t index)
{
    if (index >= TABLE_MAX_NUM) {
        return NULL;
    }

    return g_shareTable[index];
}





int BadCase()
{
    int ret = CreateShareTable();
    if (ret != 0) {
        return ret;
    }

    pthread_t threadAId;
    ret = pthread_create(&threadAId, NULL, (void *)ThreadAEntry, NULL);

    pthread_t threadBId;
    ret = pthread_create(&threadBId, NULL, (void *)ThreadBEntry, NULL);

    return 0;
}

pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;





int GoodCase()
{
    int ret = CreateShareTable();
    if (ret != 0) {
        return ret;
    }

    pthread_t threadCId;
    ret = pthread_create(&threadCId, NULL, (void *)ThreadCEntry, NULL);

    pthread_t threadDId;
    ret = pthread_create(&threadDId, NULL, (void *)ThreadDEntry, NULL);

    return 0;
}

void *ThreadCEntry(void *para)
{
    pthread_mutex_lock(&g_mutex);
    uint8_t *node = FindShareTableNode(0);
    if (node == NULL) {
        pthread_mutex_unlock(&g_mutex);
        return NULL;  
    }

    sleep(1);

    node[0] = 1;  
    pthread_mutex_unlock(&g_mutex);
}

