class MemoryPool {
public:
    explicit MemoryPool() = default;
    ~MemoryPool()
    {
        for (auto *ptr : m_allocatedBlocks) {  
            delete[] ptr;
        }
        m_allocatedBlocks.clear();
    }

    int *AllocateBlock(std::size_t blockSize)
    {
        if (blockSize <= 0) {
            return nullptr;
        }
        int *pointer = new int[blockSize];
        if (pointer != nullptr) {
            m_allocatedBlocks.insert(pointer);
        }
        return pointer;
    }

    void DeallocateBlock(int *pointer)
    {
        if (pointer != nullptr && m_allocatedBlocks.find(pointer) != m_allocatedBlocks.end()) {
            delete[] pointer;
            m_allocatedBlocks.erase(pointer);
        }
    }

private:
    std::set<int *> m_allocatedBlocks;  
};





